lessons.solution_code:
FACE_CARDS = {'K', 'Q', 'J'}


def value_of_card(card):
    """Return numeric value of a card."""
    if card in FACE_CARDS:
        return 10
    if card == "A":
        return 1
    return int(card)


def higher_card(card_one, card_two):
    """Return the higher card, or both as a tuple if equal."""
    v1, v2 = value_of_card(card_one), value_of_card(card_two)
    if v1 > v2:
        return card_one
    if v2 > v1:
        return card_two
    return (card_one, card_two)


def value_of_ace(card_one, card_two):
    """Return 11 if safe, else 1."""
    total = value_of_card(card_one) + value_of_card(card_two)
    if card_one == "A":
        total += 10
    if card_two == "A":
        total += 10
    return 11 if total + 11 <= 21 else 1


def is_blackjack(card_one, card_two):
    """Return True if hand totals 21 with an ace and a 10-value card."""
    cards = (card_one, card_two)
    return 'A' in cards and any(value_of_card(c) == 10 for c in cards)


def can_split_pairs(card_one, card_two):
    """Return True if cards have equal value."""
    return value_of_card(card_one) == value_of_card(card_two)


def can_double_down(card_one, card_two):
    """Return True if hand totals 9, 10, or 11."""
    return value_of_card(card_one) + value_of_card(card_two) in (9, 10, 11)

